      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória gerenciada (mais de 5 MB/frame) no método Update() decorrente da concatenação iterativa de strings em loop ('s += i.ToString()') e alocações frequentes de arrays de objetos na Heap gerenciada, acionando o Garbage Collector a cada poucos frames e gerando travamentos de 22.75ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");
        private static readonly int ColorId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(4096);
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                // FindObjectsByType aloca arrays na memória e varre a cena toda.
                // Se a busca for estritamente necessária, use FindObjectsByType com FindObjectsSortMode.None e evite repeti-la no Update.
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    Color randomColor = new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value);

                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(ColorId, randomColor);
                    _propertyBlock.SetColor(BaseColorId, randomColor);
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, strings são imutáveis. Cada vez que você faz 'texto += numero', o computador não altera o texto antigo; ele cria uma string totalmente nova na memória RAM gerenciada e descarta a anterior. Ao fazer isso milhares de vezes por frame no Update(), a memória fica cheia de lixo instantaneamente. Quando a Unity precisa limpar esse lixo acumulado, o coletor (Garbage Collector) congela o jogo por vários milissegundos para fazer a faxina, causando engasgos (stutters). A solução é reutilizar um StringBuilder ou evitar gerar texto a cada frame. Além disso, 'renderer.material' duplica materiais na memória, o que é evitado usando MaterialPropertyBlock."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Uso repetitivo de 'GameObject.FindObjectsOfType<GameObject>()' dentro de loops no método Update(). Este método varre exaustivamente todas as árvores de objetos presentes na cena ativa e aloca um array completo a cada execução, consumindo até 125ms de processamento de CPU.",
      "codigo_refatorado": "// Para otimizar chamadas de busca:
// 1. Remova chamadas a FindObjectsOfType dentro de Update.
// 2. Mantenha referências em coleções estáticas, Singletons, ou registre instâncias no Awake/OnEnable dos próprios objetos.
// Exemplo de registro leve de objetos:
using System.Collections.Generic;
using UnityEngine;

public class TrackedObject : MonoBehaviour
{
    public static readonly List<TrackedObject> Instances = new List<TrackedObject>();

    private void OnEnable()
    {
        Instances.Add(this);
    }

    private void OnDisable()
    {
        Instances.Remove(this);
    }
}",
      "explicacao_didatica": "O comando FindObjectsOfType funciona como pedir para alguém procurar uma pessoa andando de porta em porta em todos os prédios da cidade inteira. Se você fizer essa busca 60 vezes por segundo dentro do Update(), o processador (CPU) ficará sobrecarregado apenas procurando coisas. Em vez de procurar pela cena inteira a cada frame, é muito melhor guardar a referência do objeto uma única vez no início (Start ou Awake) ou fazer o próprio objeto se registrar em uma lista quando ele for criado."
    }
  ],
  "dicas_level_design": null
}

